import z from 'zod';
import { config } from '../../config.js';
import { PageId } from '../event.model.js';
import {
  errorPayload,
  eventSource,
  MAX_ID_LENGTH,
  pageViewPayload,
  purchasePayload,
} from './event-payloads.js';
import { MIN_OCCURRED_AT_MS } from './timestamp.js';

const PAGES_NEED_ENTITY_ID: ReadonlySet<string> = new Set([
  'category',
  'item',
] satisfies PageId[]);

const envelope = {
  event_id: z.uuid().meta({
    description:
      'Generated by the client once per event; reused in every retry.',
    example: '0b6f6f0e-5a52-4c5e-9f3a-2f1f7f6a8d11',
  }),
  source: eventSource,
  // Unix time in milliseconds. The lower bound rejects seconds: 1e12 ms is 2001-09-09,
  // while the same instant in seconds is ~1e9, far below the bound.
  occurred_at: z.int().min(MIN_OCCURRED_AT_MS).meta({
    description:
      'Unix time in milliseconds. Rejected if too far ahead of the server clock or too old (limits are configurable).',
    example: Date.now(),
  }),
  user_id: z.string().min(1).max(MAX_ID_LENGTH).optional(),
  device_id: z.string().min(1).max(MAX_ID_LENGTH).optional(),
};

const pageViewEvent = z.strictObject({
  ...envelope,
  type: z.literal('page_view'),
  payload: pageViewPayload,
});

const purchaseEvent = z.strictObject({
  ...envelope,
  source: z.literal('server'),
  type: z.literal('purchase'),
  payload: purchasePayload,
});

const errorEvent = z.strictObject({
  ...envelope,
  type: z.literal('error'),
  payload: errorPayload,
});

export const recordEventSchema = z
  .discriminatedUnion('type', [pageViewEvent, purchaseEvent, errorEvent])
  .superRefine((event, ctx) => {
    if (event.source !== 'server' && event.device_id === undefined) {
      ctx.addIssue({
        code: 'custom',
        path: ['device_id'],
        message: 'device_id is required for web and mobile events',
      });
    }

    if (event.occurred_at > Date.now() + config.maxClockSkewMs) {
      ctx.addIssue({
        code: 'custom',
        path: ['occurred_at'],
        message: `occurred_at is more than ${config.maxClockSkewMs} ms ahead of the server clock`,
      });
    }

    // A value below the minimum (seconds) already failed the range check; do not
    // report it a second time as "too old".
    if (
      event.occurred_at >= MIN_OCCURRED_AT_MS &&
      event.occurred_at < Date.now() - config.maxEventAgeMs
    ) {
      ctx.addIssue({
        code: 'custom',
        path: ['occurred_at'],
        message: `occurred_at is more than ${config.maxEventAgeMs} ms in the past`,
      });
    }

    if (
      event.type === 'page_view' &&
      PAGES_NEED_ENTITY_ID.has(event.payload.page_id)
    ) {
      if (event.payload.entity_id === undefined) {
        ctx.addIssue({
          code: 'custom',
          path: ['payload', 'entity_id'],
          message: `entity_id is required for page_id "${event.payload.page_id}"`,
        });
      }
    }
  });

export type RecordEventDto = z.infer<typeof recordEventSchema>;

export const recordEventResponseSchema = z.strictObject({
  status: z.enum(['created', 'duplicate']).meta({
    description:
      '`created` for a new event (201), `duplicate` when the `event_id` already exists (200).',
    example: 'created',
  }),
});

export type RecordEventResponseDto = z.infer<typeof recordEventResponseSchema>;
